Q["a1-cases-accusative"] = {"version":1,"id":"a1-cases-accusative","topic":"a1-cases-accusative","level":"A1","title":"Stop: accusative","passScore":3,"items":[{"id":"a1-cases-accusative-q1","type":"multiple-choice","kind":"form","prompt":"Lubię ___. (I like music.)","options":["muzyka","muzykę","muzyką","muzyki"],"correct":1,"explanation":"Lubić takes the accusative. Feminine nouns change -a to -ę: muzykę.","optionNotes":["Nominative: the dictionary form, used for the subject.",null,"Instrumental (-ą), used after być and z.","Genitive, used after nie."]},{"id":"a1-cases-accusative-q2","type":"multiple-choice","kind":"form","prompt":"Mam ___. (I have a brother.)","options":["brat","bratem","bratę","brata"],"correct":3,"explanation":"Masculine nouns for people and animals take -a in the accusative: brata.","optionNotes":["Nominative. English does not change the noun here, Polish does.","Instrumental, as in Jestem bratem Anny.","-ę is the feminine ending.",null]},{"id":"a1-cases-accusative-q3","type":"multiple-choice","kind":"form","prompt":"Kupuję ___ telefon.","options":["nowy","nowego","nową","nowe"],"correct":0,"explanation":"Telefon is a masculine thing, so nothing changes: nowy telefon.","optionNotes":[null,"-ego is for masculine people and animals: nowego kolegę.","-ą is the feminine ending.","-e is the neuter ending."]},{"id":"a1-cases-accusative-q4","type":"multiple-choice","kind":"form","prompt":"Which sentence is correct?","options":["Piję dobra kawę.","Piję dobrą kawa.","Piję dobrą kawę.","Piję dobra kawa."],"correct":2,"explanation":"Both words change: the adjective takes -ą and the noun takes -ę.","optionNotes":["The adjective must change too.","The noun must change too.",null,"This is the nominative; the object needs the accusative."]}]};
Q["a1-cases-instrumental-identity"] = {"version":1,"id":"a1-cases-instrumental-identity","topic":"a1-cases-instrumental-identity","level":"A1","title":"Stop: instrumental","passScore":3,"items":[{"id":"a1-cases-instrumental-identity-q1","type":"multiple-choice","kind":"form","prompt":"Jestem ___. (I'm a student. – a man speaking)","options":["student","studentą","studenta","studentem"],"correct":3,"explanation":"A noun after być takes the instrumental: masculine -em.","optionNotes":["The nominative: English does not change the noun, Polish does.","-ą is the feminine ending.","Studenta is another case (accusative).",null]},{"id":"a1-cases-instrumental-identity-q2","type":"multiple-choice","kind":"form","prompt":"Ona jest ___. (She's a teacher.)","options":["nauczycielką","nauczycielka","nauczycielkę","nauczycielem"],"correct":0,"explanation":"Feminine nouns change -a to -ą after być.","optionNotes":[null,"The nominative.","-ę is another case (accusative).","The masculine form; for a woman use nauczycielką."]},{"id":"a1-cases-instrumental-identity-q3","type":"multiple-choice","kind":"form","prompt":"Kawa z ___, proszę. (Coffee with milk, please.)","options":["mleko","mlekiem","mleka","mlekem"],"correct":1,"explanation":"Z meaning 'with' takes the instrumental; after k the ending is -iem: mlekiem.","optionNotes":["The nominative.",null,"Mleka is another case (genitive).","After k the ending is -iem."]},{"id":"a1-cases-instrumental-identity-q4","type":"multiple-choice","kind":"form","prompt":"Which sentence is correct?","options":["To jest studentem.","Jestem zmęczonym.","On jest lekarzem.","Ona jest lekarka."],"correct":2,"explanation":"A noun after być is in the instrumental: lekarzem.","optionNotes":["After to jest the noun stays in the nominative: to jest student.","An adjective alone stays in the nominative: zmęczony.",null,"Lekarka must change: lekarką."]}]};
Q["a1-cases-nominative"] = {"version":1,"id":"a1-cases-nominative","topic":"a1-cases-nominative","level":"A1","title":"Stop: nominative and adjectives","passScore":3,"items":[{"id":"a1-cases-nominative-q1","type":"multiple-choice","kind":"form","prompt":"To jest ___ praca. (This is a new job.)","options":["nowy","nowe","nowa","nowo"],"correct":2,"explanation":"Praca is feminine, so the adjective ends in -a: nowa praca.","optionNotes":["-y is masculine.","-e is neuter.",null,"Nowo is not an adjective form."]},{"id":"a1-cases-nominative-q2","type":"multiple-choice","kind":"form","prompt":"To jest ___ okno. (This is a high window.)","options":["wysoki","wysoka","wysokie","wysoky"],"correct":2,"explanation":"Okno is neuter: -e, and after k it is -ie: wysokie.","optionNotes":["Masculine.","Feminine.",null,"After k write i, never y."]},{"id":"a1-cases-nominative-q3","type":"multiple-choice","kind":"form","prompt":"___ to jest? — To jest lampa.","options":["Kto","Co","Jak","Gdzie"],"correct":1,"explanation":"Co to jest? asks about things.","optionNotes":["Kto is for people and animals.",null,"Jak means 'how'.","Gdzie means 'where'."]},{"id":"a1-cases-nominative-q4","type":"multiple-choice","kind":"form","prompt":"Which is correct? (good coffee)","options":["dobry kawa","dobre kawa","dobrą kawa","dobra kawa"],"correct":3,"explanation":"Kawa is feminine: dobra kawa.","optionNotes":["Masculine adjective with a feminine noun.","Neuter adjective with a feminine noun.","-ą is not the nominative.",null]}]};
Q["a1-functions-greetings-introductions"] = {"version":1,"id":"a1-functions-greetings-introductions","topic":"a1-functions-greetings-introductions","level":"A1","title":"Stop: greetings","passScore":3,"items":[{"id":"a1-functions-greetings-introductions-q1","type":"multiple-choice","kind":"function","prompt":"You walk into a small shop in the morning. What do you say?","options":["Cześć!","Dzień dobry!","Dobranoc!","Na razie!"],"correct":1,"explanation":"Dzień dobry is the formal hello for shops, offices and strangers.","optionNotes":["Cześć is only for friends and family.",null,"Dobranoc means good night, when you leave late or go to bed.","Na razie is an informal goodbye."]},{"id":"a1-functions-greetings-introductions-q2","type":"multiple-choice","kind":"function","prompt":"How do you ask a friend how they are?","options":["Jak się masz?","Jak się jesteś?","Jak się pan ma?","Jak masz?"],"correct":0,"explanation":"The informal question is Jak się masz? It uses masz (have), not jesteś (are).","optionNotes":[null,"A calque of English 'how are you'; Polish uses masz here.","This is formal, for a man you don't know well.","się is missing."]},{"id":"a1-functions-greetings-introductions-q3","type":"multiple-choice","kind":"form","prompt":"Mam ___ imię Ewa. (My name is Ewa.)","options":["na","moje","jest","się"],"correct":0,"explanation":"The fixed phrase is Mam na imię … (literally 'I have the name …').","optionNotes":[null,"A calque of 'my name'.","A calque of 'is'.","się belongs to Nazywam się …"]},{"id":"a1-functions-greetings-introductions-q4","type":"multiple-choice","kind":"function","prompt":"At noon you leave a meeting with a new client. What do you say?","options":["Cześć!","Na razie!","Do widzenia!","Dobranoc!"],"correct":2,"explanation":"Do widzenia is the formal goodbye.","optionNotes":["Cześć is informal: friends and family only.","Na razie is informal.",null,"Dobranoc is for late in the evening."]}]};
Q["a1-functions-personal-details"] = {"version":1,"id":"a1-functions-personal-details","topic":"a1-functions-personal-details","level":"A1","title":"Stop: personal details","passScore":3,"items":[{"id":"a1-functions-personal-details-q1","type":"multiple-choice","kind":"function","prompt":"How do you ask a man you don't know where he is from?","options":["Skąd jesteś?","Gdzie pan jest?","Skąd pan jesteś?","Skąd pan jest?"],"correct":3,"explanation":"To a stranger use pan + the he form: Skąd pan jest?","optionNotes":["Informal: for friends.","Gdzie pan jest? means 'Where are you (now)?'","Pan takes jest, not jesteś.",null]},{"id":"a1-functions-personal-details-q2","type":"multiple-choice","kind":"function","prompt":"I'm 30.","options":["Jestem trzydzieści lat.","Mam trzydzieści lat.","Mam trzydzieści lata.","Jestem trzydzieści."],"correct":1,"explanation":"Age uses mieć: Mam … lat.","optionNotes":["Age uses mieć, not być.",null,"After 30 say lat; lata is for numbers ending in 2, 3, 4.","Age uses mieć, and lat is missing."]},{"id":"a1-functions-personal-details-q3","type":"multiple-choice","kind":"form","prompt":"Mieszkam w ___. (I live in Kraków.)","options":["Krakowie","Kraków","Krakowa","Krakowem"],"correct":0,"explanation":"After w (in) the city changes: w Krakowie.","optionNotes":[null,"The dictionary form does not follow w.","Krakowa follows z (from): z Krakowa.","Krakowem is the instrumental."]},{"id":"a1-functions-personal-details-q4","type":"multiple-choice","kind":"form","prompt":"Mam dwadzieścia trzy ___. (I'm 23.)","options":["lat","lata","rok","roku"],"correct":1,"explanation":"After numbers ending in 2, 3, 4 (not 12–14) say lata.","optionNotes":["Lat follows the other numbers: dwadzieścia pięć lat.",null,"Rok is one year.","Roku is another form of rok."]}]};
Q["a1-grammar-alphabet-pronunciation"] = {"version":1,"id":"a1-grammar-alphabet-pronunciation","topic":"a1-grammar-alphabet-pronunciation","level":"A1","title":"Stop: alphabet and stress","passScore":3,"items":[{"id":"a1-grammar-alphabet-pronunciation-q1","type":"multiple-choice","kind":"form","prompt":"Warszawa = war-sza-wa. Which syllable is stressed?","options":["war","sza","wa"],"correct":1,"explanation":"Polish stresses the second-to-last syllable: war-SZA-wa.","optionNotes":["English habit: stress on the first syllable.",null,"The last syllable is not stressed in Polish words like this."]},{"id":"a1-grammar-alphabet-pronunciation-q2","type":"multiple-choice","kind":"form","prompt":"Which spelling makes the same sound as ż?","options":["rz","sz","cz","z"],"correct":0,"explanation":"rz and ż are two spellings of one sound, like the s in pleasure.","optionNotes":[null,"sz is the sh in shop.","cz is the ch in church.","z is the z in zoo."]},{"id":"a1-grammar-alphabet-pronunciation-q3","type":"multiple-choice","kind":"form","prompt":"Which letter sounds like the w in English water?","options":["w","ł","u","l"],"correct":1,"explanation":"ł sounds like English w. Polish w sounds like v.","optionNotes":["Polish w sounds like v, as in van.",null,"u is a vowel, like the oo in book.","l is a clear l, as in leaf."]},{"id":"a1-grammar-alphabet-pronunciation-q4","type":"multiple-choice","kind":"form","prompt":"Which spelling is correct? (Thank you.)","options":["Dziekuje.","Dziękuje.","Dziekuję.","Dziękuję."],"correct":3,"explanation":"Both e's in dziękuję have the mark: dzię-ku-ję. The marks are part of the spelling.","optionNotes":["Both marks are missing.","The final ę is missing its mark.","The first ę is missing its mark.",null]}]};
Q["a1-grammar-gender-of-nouns"] = {"version":1,"id":"a1-grammar-gender-of-nouns","topic":"a1-grammar-gender-of-nouns","level":"A1","title":"Stop: gender of nouns","passScore":3,"items":[{"id":"a1-grammar-gender-of-nouns-q1","type":"multiple-choice","kind":"form","prompt":"Which noun is feminine?","options":["dom","noc","okno","tata"],"correct":1,"explanation":"Noc is feminine although it ends in a consonant: ta noc.","optionNotes":["A consonant ending: masculine, ten dom.",null,"-o: neuter, to okno.","A man's word in -a is masculine: ten tata."]},{"id":"a1-grammar-gender-of-nouns-q2","type":"multiple-choice","kind":"form","prompt":"___ okno (this window)","options":["ten","ta","to"],"correct":2,"explanation":"Okno ends in -o, so it is neuter: to okno.","optionNotes":["Ten is masculine.","Ta is feminine.",null]},{"id":"a1-grammar-gender-of-nouns-q3","type":"multiple-choice","kind":"form","prompt":"___ kolega (this friend)","options":["ten","ta","to"],"correct":0,"explanation":"Kolega is a man, so it is masculine although it ends in -a: ten kolega.","optionNotes":[null,"The -a ending misleads: kolega is a man.","To is neuter."]},{"id":"a1-grammar-gender-of-nouns-q4","type":"multiple-choice","kind":"form","prompt":"Gdzie jest telefon? — ___ jest tu.","options":["Ono","On","Ona","One"],"correct":1,"explanation":"Telefon is masculine, so 'it' is on.","optionNotes":["Ono is only for neuter nouns, not for every thing.",null,"Ona is for feminine nouns.","One is plural."]}]};
Q["a1-grammar-pronouns-pan-pani"] = {"version":1,"id":"a1-grammar-pronouns-pan-pani","topic":"a1-grammar-pronouns-pan-pani","level":"A1","title":"Stop: pronouns and pan / pani","passScore":3,"items":[{"id":"a1-grammar-pronouns-pan-pani-q1","type":"multiple-choice","kind":"form","prompt":"Anna i Ewa? ___ są tu.","options":["Oni","One","Ono","Wy"],"correct":1,"explanation":"A group of women is one. Oni needs at least one man.","optionNotes":["Oni is for a group with at least one man.",null,"Ono is 'it', for neuter nouns.","Wy is 'you', not 'they'."]},{"id":"a1-grammar-pronouns-pan-pani-q2","type":"multiple-choice","kind":"function","prompt":"To an older man you don't know: How are you?","options":["Jak się masz?","Jak się pan ma?","Jak się pan masz?","Jak się macie?"],"correct":1,"explanation":"With strangers use pan (to a man) and the he form of the verb: ma.","optionNotes":["Informal: too familiar for a stranger.",null,"Pan takes the he form ma, not the you form masz.","Wy is never the polite form for one person."]},{"id":"a1-grammar-pronouns-pan-pani-q3","type":"multiple-choice","kind":"form","prompt":"Which pronoun replaces dziecko (a child)?","options":["on","ona","ono","one"],"correct":2,"explanation":"Dziecko is a neuter noun, so the pronoun is ono.","optionNotes":["On is for masculine nouns.","Ona is for feminine nouns.",null,"One is a plural pronoun."]},{"id":"a1-grammar-pronouns-pan-pani-q4","type":"multiple-choice","kind":"form","prompt":"Marek i Ola? ___ są tam.","options":["One","Oni","On","Ona"],"correct":1,"explanation":"The group has a man (Marek), so the pronoun is oni.","optionNotes":["One is only for groups with no men.",null,"On is one man; this is two people.","Ona is one woman; this is two people."]}]};
Q["a1-verbs-byc"] = {"version":1,"id":"a1-verbs-byc","topic":"a1-verbs-byc","level":"A1","title":"Stop: być","passScore":3,"items":[{"id":"a1-verbs-byc-q1","type":"multiple-choice","kind":"form","prompt":"My ___ tu. (We're here.)","options":["jesteśmy","jesteście","są","jest"],"correct":0,"explanation":"my → jesteśmy.","optionNotes":[null,"Jesteście goes with wy (you, plural).","Są goes with oni / one (they).","Jest is the he / she / it form."]},{"id":"a1-verbs-byc-q2","type":"multiple-choice","kind":"form","prompt":"Oni ___ tam. (They're over there.)","options":["jest","są","jesteście","jestem"],"correct":1,"explanation":"oni → są.","optionNotes":["Jest is singular: he / she / it is.",null,"Jesteście goes with wy.","Jestem is I am."]},{"id":"a1-verbs-byc-q3","type":"multiple-choice","kind":"form","prompt":"___ moje dzieci. (These are my children.)","options":["To jest","To są","Ten jest","To jesteś"],"correct":1,"explanation":"Dzieci is plural, so to są. To itself never changes.","optionNotes":["To jest is for one person or thing.",null,"Polish says to, not ten, when pointing: to jest, to są.","Jesteś is the you form."]},{"id":"a1-verbs-byc-q4","type":"multiple-choice","kind":"form","prompt":"Pani ___ bardzo miła. (You're very nice. – to a woman)","options":["jesteś","jest","jesteście","są"],"correct":1,"explanation":"Pani takes the she form of the verb: pani jest.","optionNotes":["Jesteś is the ty form; pani uses the she form.",null,"Wy is never the polite form for one person.","Są is plural."]}]};
Q["a1-vocabulary-family-people"] = {"version":1,"id":"a1-vocabulary-family-people","topic":"a1-vocabulary-family-people","level":"A1","title":"Stop: family and people","passScore":3,"items":[{"id":"a1-vocabulary-family-people-q1","type":"multiple-choice","kind":"form","prompt":"___ brat (my brother)","options":["mój","moja","moje"],"correct":0,"explanation":"Brat is masculine: mój brat.","optionNotes":[null,"Moja is feminine.","Moje is neuter."]},{"id":"a1-vocabulary-family-people-q2","type":"multiple-choice","kind":"form","prompt":"What is the female form of lekarz (doctor)?","options":["lekarza","lekarka","lekarzka","lekarkę"],"correct":1,"explanation":"lekarz → lekarka.","optionNotes":["Lekarza is another case of lekarz.",null,"Not a word: rz drops before -ka: lekarz → lekarka.","Lekarkę is another case of lekarka."]},{"id":"a1-vocabulary-family-people-q3","type":"multiple-choice","kind":"form","prompt":"I'm Polish. (a woman speaking)","options":["Jestem polska.","Jestem Polakiem.","Jestem Polka.","Jestem Polką."],"correct":3,"explanation":"Use the nationality noun in the instrumental, with a capital letter: Polką.","optionNotes":["Polska is an adjective (and the name of the country); use the noun.","Polakiem is the man's form.","After jestem the noun changes: -a → -ą.",null]},{"id":"a1-vocabulary-family-people-q4","type":"multiple-choice","kind":"form","prompt":"Which word means 'parents'?","options":["krewni","rodzina","rodzice","dziadkowie"],"correct":2,"explanation":"Rodzice means parents.","optionNotes":["Krewni means relatives.","Rodzina means family.",null,"Dziadkowie means grandparents."]}]};
Q["a1-vocabulary-numbers-days-months"] = {"version":1,"id":"a1-vocabulary-numbers-days-months","topic":"a1-vocabulary-numbers-days-months","level":"A1","title":"Stop: numbers, days, months","passScore":3,"items":[{"id":"a1-vocabulary-numbers-days-months-q1","type":"multiple-choice","kind":"form","prompt":"15 = ?","options":["pięćnaście","piętnaście","piętnascie","pięćdziesiąt"],"correct":1,"explanation":"Fifteen is spelled with t: piętnaście.","optionNotes":["Built from pięć, but the spelling is piętnaście.",null,"The ś in -naście is missing.","Pięćdziesiąt is 50."]},{"id":"a1-vocabulary-numbers-days-months-q2","type":"multiple-choice","kind":"form","prompt":"How do you say 'on Saturday'?","options":["w sobota","w sobotę","na sobotę","w sobote"],"correct":1,"explanation":"'On' + a day is w + a changed ending: sobota → w sobotę.","optionNotes":["The ending must change: -a → -ę.",null,"Na sobotę means 'for Saturday'.","The ę needs its mark."]},{"id":"a1-vocabulary-numbers-days-months-q3","type":"multiple-choice","kind":"form","prompt":"Which day comes after czwartek (Thursday)?","options":["środa","piątek","wtorek","sobota"],"correct":1,"explanation":"poniedziałek, wtorek, środa, czwartek, piątek, sobota, niedziela.","optionNotes":["Środa is Wednesday, the day before czwartek.",null,"Wtorek is Tuesday.","Sobota is Saturday, two days after czwartek."]},{"id":"a1-vocabulary-numbers-days-months-q4","type":"multiple-choice","kind":"form","prompt":"42 = ?","options":["czterdzieści dwa","czterdzieści i dwa","czterdziesiąt dwa","cztery dwa"],"correct":0,"explanation":"Tens + units, with no 'and': czterdzieści dwa.","optionNotes":[null,"No 'and' inside a number.","-dziesiąt is for 50–90; 40 is czterdzieści.","That is just 'four two'."]}]};
